<?php
declare(strict_types=1);
namespace Moves\Services;
use DateTimeImmutable;
use InvalidArgumentException;
use MovesCode\Model\Connection;
use PDO;

/** Importa linhas para revisão. Confirmar uma linha somente vincula a um lançamento já existente. */
final class BankReconciliation
{
    private PDO $pdo;
    public function __construct(private readonly int $contextId) { $this->pdo=Connection::get(); }
    public function lines(): array { $q=$this->pdo->prepare('SELECT l.*,a.name account,e.description entry_description FROM finance_reconciliation_lines l INNER JOIN finance_accounts a ON a.id=l.account_id LEFT JOIN finance_entries e ON e.id=l.matched_entry_id WHERE l.financial_context_id=? ORDER BY l.status=\'pending\' DESC,l.occurred_on DESC,l.id DESC');$q->execute([$this->contextId]);return $q->fetchAll(PDO::FETCH_ASSOC); }
    public function importCsv(array $file,mixed $accountId,int $userId): int { $account=$this->account($accountId);if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file((string)($file['tmp_name']??'')))throw new InvalidArgumentException('Selecione um CSV válido.');if(($file['size']??0)>5*1024*1024)throw new InvalidArgumentException('O arquivo pode ter até 5 MB.');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!in_array($mime,['text/plain','text/csv','application/csv','application/vnd.ms-excel'],true))throw new InvalidArgumentException('Envie um CSV, não um arquivo executável.');$name=basename((string)$file['name']);if(!str_ends_with(strtolower($name),'.csv'))throw new InvalidArgumentException('Envie um arquivo com extensão .csv.');$hash=hash_file('sha256',$file['tmp_name']);$base=BASE_PATH.'/storage/reconciliation';if(!is_dir($base)&&!mkdir($base,0750,true)&&!is_dir($base))throw new InvalidArgumentException('Não foi possível preparar o armazenamento.');$path=$base.'/'.$this->contextId.'-'.bin2hex(random_bytes(16)).'.csv';if(!move_uploaded_file($file['tmp_name'],$path))throw new InvalidArgumentException('Não foi possível guardar o arquivo.');$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('INSERT INTO finance_reconciliation_imports (financial_context_id,account_id,original_name,stored_path,mime_type,checksum,imported_by) VALUES (?,?,?,?,?,?,?)');$q->execute([$this->contextId,$account,$name,$path,$mime,$hash,$userId]);$import=(int)$this->pdo->lastInsertId();$fh=fopen($path,'rb');$header=fgetcsv($fh,0,';')?:fgetcsv($fh,0,',');if($header===false)throw new InvalidArgumentException('CSV sem cabeçalho.');$normal=array_map(static fn($v)=>strtolower(trim((string)$v)),$header);$dateIndex=array_search('data',$normal,true);$descriptionIndex=array_search('descrição',$normal,true);if($descriptionIndex===false)$descriptionIndex=array_search('descricao',$normal,true);$amountIndex=array_search('valor',$normal,true);if($dateIndex===false||$descriptionIndex===false||$amountIndex===false)throw new InvalidArgumentException('O CSV precisa das colunas Data, Descrição e Valor.');$insert=$this->pdo->prepare('INSERT INTO finance_reconciliation_lines (financial_context_id,import_id,account_id,occurred_on,description,amount_cents,external_id) VALUES (?,?,?,?,?,?,?)');$count=0;while(($row=fgetcsv($fh,0,';'))!==false||($row=fgetcsv($fh,0,','))!==false){if(count($row)<=max($dateIndex,$descriptionIndex,$amountIndex))continue;$date=$this->date($row[$dateIndex]);$description=mb_substr(trim((string)$row[$descriptionIndex]),0,255);if($description==='')continue;$amount=$this->signedCents($row[$amountIndex]);$insert->execute([$this->contextId,$import,$account,$date,$description,$amount,hash('sha256',$date.'|'.$description.'|'.$amount)]);$count++;}fclose($fh);if($count===0)throw new InvalidArgumentException('Nenhuma linha válida foi encontrada.');$this->pdo->commit();return $count;}catch(\Throwable $e){if(isset($fh)&&is_resource($fh))fclose($fh);if($this->pdo->inTransaction())$this->pdo->rollBack();@unlink($path);throw $e;}}
    public function review(mixed $lineId,mixed $entryId,string $status,int $userId): void { $line=filter_var($lineId,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($line===false)throw new InvalidArgumentException('Linha inválida.');if(!in_array($status,['matched','ignored','reversed'],true))throw new InvalidArgumentException('Situação inválida.');$entry=null;if($status==='matched'){$entry=filter_var($entryId,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$q=$this->pdo->prepare('SELECT id FROM finance_entries WHERE id=? AND financial_context_id=?');$q->execute([$entry,$this->contextId]);if($entry===false||$q->fetchColumn()===false)throw new InvalidArgumentException('Lançamento inválido para esta área.');}$q=$this->pdo->prepare('UPDATE finance_reconciliation_lines SET status=?,matched_entry_id=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND financial_context_id=?');$q->execute([$status,$entry,$userId,$line,$this->contextId]);if($q->rowCount()===0)throw new InvalidArgumentException('Linha não encontrada.');}
    private function account(mixed $id): int {$id=filter_var($id,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$q=$this->pdo->prepare("SELECT id FROM finance_accounts WHERE id=? AND financial_context_id=? AND type <> 'credit_card' AND archived_at IS NULL AND status='active'");$q->execute([$id,$this->contextId]);if($id===false||$q->fetchColumn()===false)throw new InvalidArgumentException('Conta bancária inválida.');return (int)$id;}
    private function date(mixed $value): string {$value=trim((string)$value);foreach(['!d/m/Y','!Y-m-d'] as $format){$d=DateTimeImmutable::createFromFormat($format,$value);if($d&&$d->format(str_contains($format,'d/m')?'d/m/Y':'Y-m-d')===$value)return $d->format('Y-m-d');}throw new InvalidArgumentException('Data inválida no CSV.');}
    private function signedCents(mixed $value): int {$v=trim((string)$value);$negative=str_starts_with($v,'-');$v=ltrim($v,'+-');$c=Finance::parseCents($v);return $negative?- $c:$c;}
}
